import React, { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { useNotifications } from '../../context/NotificationContext';
import styles from './PurchaseHistory.module.css';

class InventoryManager extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            orders: [],
            loading: true,
            error: null,
            sortField: 'createdAt',
            sortOrder: 'desc',
            filterStatus: '',
            searchTerm: '',
            selectedOrders: [],
            expandedOrder: null
        };
    }

    componentDidMount() {
        this.fetchOrders();
    }

    componentDidUpdate(prevProps, prevState) {
        if (prevState.sortField !== this.state.sortField ||
            prevState.sortOrder !== this.state.sortOrder ||
            prevState.filterStatus !== this.state.filterStatus) {
            this.fetchOrders();
        }
    }

    fetchOrders = async () => {
        this.setState({ loading: true, error: null });
        try {
            const { token } = this.props;
            const query = new URLSearchParams({
                sortBy: this.state.sortField,
                sortOrder: this.state.sortOrder,
                ...(this.state.filterStatus && { status: this.state.filterStatus })
            }).toString();

            const response = await fetch(`http://localhost:5000/api/orders?${query}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                this.setState({
                    orders: data.data.orders || [],
                    loading: false
                });
            } else {
                throw new Error(data.message);
            }
        } catch (error) {
            this.setState({
                error: error.message,
                loading: false
            });
        }
    };

    onInventoryUpdate = async (orderId, updates) => {
        try {
            const { token, onUpdate } = this.props;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(updates)
            });

            const data = await response.json();
            if (data.success) {
                this.fetchOrders();
                if (onUpdate) onUpdate(data.data.order);
                return { success: true, message: 'Заказ обновлен успешно' };
            } else {
                return { success: false, message: data.message };
            }
        } catch (error) {
            return { success: false, message: error.message };
        }
    };

    onDeleteOrder = async (orderId) => {
        if (!window.confirm('Удалить этот заказ?')) return;

        try {
            const { token } = this.props;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            const data = await response.json();
            if (data.success) {
                this.fetchOrders();
                this.props.showNotification('Заказ удален', 'success');
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка удаления', 'error');
        }
    };

    handleSort = (field) => {
        this.setState(prev => ({
            sortField: field,
            sortOrder: prev.sortField === field && prev.sortOrder === 'asc' ? 'desc' : 'asc'
        }));
    };

    handleStatusFilter = (status) => {
        this.setState({ filterStatus: status });
    };

    handleSearch = (e) => {
        this.setState({ searchTerm: e.target.value });
    };

    handleSelectOrder = (orderId) => {
        this.setState(prev => ({
            selectedOrders: prev.selectedOrders.includes(orderId)
                ? prev.selectedOrders.filter(id => id !== orderId)
                : [...prev.selectedOrders, orderId]
        }));
    };

    toggleOrderExpand = (orderId) => {
        this.setState(prev => ({
            expandedOrder: prev.expandedOrder === orderId ? null : orderId
        }));
    };

    handleStatusChange = async (orderId, newStatus) => {
        try {
            const { token } = this.props;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}/status`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ status: newStatus })
            });

            const data = await response.json();
            if (data.success) {
                this.fetchOrders();
                this.props.showNotification(`Статус заказа изменен на "${newStatus}"`, 'success');
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка обновления статуса', 'error');
        }
    };

    getStatusColor = (status) => {
        const colors = {
            'created': '#ffb74d',
            'confirmed': '#4fc3f7',
            'processing': '#9575cd',
            'shipped': '#64b5f6',
            'delivered': '#81c784',
            'cancelled': '#e57373'
        };
        return colors[status] || '#757575';
    };

    getStatusText = (status) => {
        const texts = {
            'created': 'Создан',
            'confirmed': 'Подтвержден',
            'processing': 'В обработке',
            'shipped': 'Отправлен',
            'delivered': 'Доставлен',
            'cancelled': 'Отменен'
        };
        return texts[status] || status;
    };

    render() {
        const {
            orders,
            loading,
            error,
            sortField,
            sortOrder,
            searchTerm,
            selectedOrders,
            expandedOrder
        } = this.state;

        const filteredOrders = orders.filter(order => {
            if (!searchTerm) return true;
            const searchLower = searchTerm.toLowerCase();
            return (
                order.orderNumber.toLowerCase().includes(searchLower) ||
                order.supplier?.name?.toLowerCase().includes(searchLower) ||
                order.notes?.toLowerCase().includes(searchLower)
            );
        });

        if (loading) return <div className={styles.loading}>Загрузка заказов...</div>;
        if (error) return <div className={styles.error}>{error}</div>;

        return (
            <div className={styles.inventoryManager}>
                <div className={styles.controls}>
                    <div className={styles.searchBox}>
                        <input
                            type="text"
                            placeholder="Поиск по номеру заказа или поставщику..."
                            value={searchTerm}
                            onChange={this.handleSearch}
                            className={styles.searchInput}
                        />
                    </div>

                    <div className={styles.filterControls}>
                        <button
                            onClick={() => this.handleSort('createdAt')}
                            className={`${styles.sortBtn} ${sortField === 'createdAt' ? styles.active : ''}`}
                        >
                            Дата {sortField === 'createdAt' && (sortOrder === 'asc' ? '↑' : '↓')}
                        </button>

                        <button
                            onClick={() => this.handleSort('totalCost')}
                            className={`${styles.sortBtn} ${sortField === 'totalCost' ? styles.active : ''}`}
                        >
                            Сумма {sortField === 'totalCost' && (sortOrder === 'asc' ? '↑' : '↓')}
                        </button>

                        <select
                            onChange={(e) => this.handleStatusFilter(e.target.value)}
                            className={styles.statusFilter}
                            value={this.state.filterStatus}
                        >
                            <option value="">Все статусы</option>
                            <option value="created">Создан</option>
                            <option value="confirmed">Подтвержден</option>
                            <option value="processing">В обработке</option>
                            <option value="shipped">Отправлен</option>
                            <option value="delivered">Доставлен</option>
                            <option value="cancelled">Отменен</option>
                        </select>
                    </div>
                </div>

                <div className={styles.ordersList}>
                    {filteredOrders.length === 0 ? (
                        <div className={styles.noResults}>
                            <p>Заказы не найдены</p>
                        </div>
                    ) : (
                        filteredOrders.map(order => (
                            <div key={order._id} className={styles.orderCard}>
                                <div
                                    className={styles.orderHeader}
                                    onClick={() => this.toggleOrderExpand(order._id)}
                                >
                                    <div className={styles.orderInfo}>
                                        <div className={styles.orderNumber}>
                                            <strong>{order.orderNumber}</strong>
                                            <span className={styles.orderDate}>
                                                {new Date(order.createdAt).toLocaleDateString('ru-RU')}
                                            </span>
                                        </div>
                                        <div className={styles.supplierInfo}>
                                            <span className={styles.supplierName}>
                                                Поставщик: {order.supplier?.name || 'Неизвестен'}
                                            </span>
                                            <span className={styles.supplierCity}>
                                                {order.supplier?.address?.city || ''}
                                            </span>
                                        </div>
                                    </div>

                                    <div className={styles.orderSummary}>
                                        <div className={styles.orderStats}>
                                            <span className={styles.orderQuantity}>
                                                {order.totalQuantity} шт.
                                            </span>
                                            <span className={styles.orderTotal}>
                                                {order.totalCost.toFixed(2)} ₽
                                            </span>
                                        </div>
                                        <div
                                            className={styles.orderStatus}
                                            style={{ backgroundColor: this.getStatusColor(order.status) }}
                                        >
                                            {this.getStatusText(order.status)}
                                        </div>
                                        <div className={styles.expandIcon}>
                                            {expandedOrder === order._id ? '▲' : '▼'}
                                        </div>
                                    </div>
                                </div>

                                {expandedOrder === order._id && (
                                    <div className={styles.orderDetails}>
                                        <div className={styles.purchasesSection}>
                                            <h4>Состав заказа:</h4>
                                            <div className={styles.purchasesList}>
                                                {order.purchases?.map((purchase, index) => (
                                                    <div key={purchase._id || index} className={styles.purchaseItem}>
                                                        <div className={styles.purchaseProduct}>
                                                            <strong>{purchase.product?.name || 'Неизвестный товар'}</strong>
                                                            <span>{purchase.product?.sku || 'N/A'}</span>
                                                        </div>
                                                        <div className={styles.purchaseDetails}>
                                                            <span>{purchase.quantity} шт.</span>
                                                            <span>{purchase.purchasePrice} ₽/шт.</span>
                                                            <span className={styles.purchaseTotal}>
                                                                {(purchase.quantity * purchase.purchasePrice).toFixed(2)} ₽
                                                            </span>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>

                                        <div className={styles.orderMeta}>
                                            <div className={styles.metaItem}>
                                                <strong>Создал:</strong>
                                                <span>{order.createdBy?.username || 'Неизвестно'}</span>
                                            </div>
                                            {order.estimatedDeliveryDate && (
                                                <div className={styles.metaItem}>
                                                    <strong>Ожидаемая доставка:</strong>
                                                    <span>{new Date(order.estimatedDeliveryDate).toLocaleDateString('ru-RU')}</span>
                                                </div>
                                            )}
                                            {order.deliveryDate && (
                                                <div className={styles.metaItem}>
                                                    <strong>Дата доставки:</strong>
                                                    <span>{new Date(order.deliveryDate).toLocaleDateString('ru-RU')}</span>
                                                </div>
                                            )}
                                            {order.notes && (
                                                <div className={styles.metaItem}>
                                                    <strong>Примечания:</strong>
                                                    <span>{order.notes}</span>
                                                </div>
                                            )}
                                        </div>

                                        <div className={styles.orderActions}>
                                            {order.status !== 'delivered' && order.status !== 'cancelled' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'delivered')}
                                                    className={styles.deliverBtn}
                                                >
                                                    Отметить доставленным
                                                </button>
                                            )}

                                            {order.status !== 'cancelled' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'cancelled')}
                                                    className={styles.cancelBtn}
                                                >
                                                    Отменить заказ
                                                </button>
                                            )}

                                            {order.status === 'created' && (
                                                <button
                                                    onClick={() => this.onDeleteOrder(order._id)}
                                                    className={styles.deleteBtn}
                                                >
                                                    Удалить заказ
                                                </button>
                                            )}

                                            {order.status === 'confirmed' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'processing')}
                                                    className={styles.processBtn}
                                                >
                                                    Начать обработку
                                                </button>
                                            )}

                                            {order.status === 'processing' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'shipped')}
                                                    className={styles.shipBtn}
                                                >
                                                    Отправить
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>

                <div className={styles.stats}>
                    <div className={styles.stat}>
                        <span>Всего заказов:</span>
                        <strong>{filteredOrders.length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>Доставлено:</span>
                        <strong>{filteredOrders.filter(o => o.status === 'delivered').length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>В обработке:</span>
                        <strong>{filteredOrders.filter(o => o.status === 'processing').length}</strong>
                    </div>
                    <div className={styles.stat}>
                        <span>Общая сумма:</span>
                        <strong>
                            {filteredOrders.reduce((sum, o) => sum + o.totalCost, 0).toFixed(2)} ₽
                        </strong>
                    </div>
                </div>
            </div>
        );
    }
}

function PurchaseHistory() {
    const { user, token } = useContext(AuthContext);
    const { showSuccess, showError, showInfo } = useNotifications();
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState(null);

    useEffect(() => {
        if (user?.role === 'admin') {
            fetchOrders();
            fetchStats();
        }
    }, [user]);

    const fetchOrders = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/orders', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                setOrders(data.data.orders || []);
            }
            setLoading(false);
        } catch (error) {
            console.error('Ошибка загрузки заказов:', error);
            setLoading(false);
        }
    };

    const fetchStats = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/orders/stats', {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await response.json();

            if (data.success) {
                setStats(data.data.overallStats);
            }
        } catch (error) {
            console.error('Ошибка загрузки статистики:', error);
        }
    };

    const showNotification = (message, type) => {
        if (type === 'success') showSuccess(message);
        else if (type === 'error') showError(message);
        else if (type === 'warning') showInfo(message);
        else showInfo(message);
    };

    if (user?.role !== 'admin') {
        return (
            <div className={styles.accessDenied}>
                <h2>Доступ запрещен</h2>
                <p>Эта страница доступна только администраторам</p>
            </div>
        );
    }

    if (loading) {
        return <div className={styles.loading}>Загрузка истории заказов...</div>;
    }

    return (
        <div className={styles.purchaseHistory}>
            <h2 className={styles.title}>История заказов у поставщиков</h2>

            {stats && (
                <div className={styles.statsOverview}>
                    <div className={styles.statCard}>
                        <h3>Всего заказов</h3>
                        <p className={styles.statNumber}>{stats.totalOrders || 0}</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Всего товаров</h3>
                        <p className={styles.statNumber}>{stats.totalItems || 0}</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Общая стоимость</h3>
                        <p className={styles.statNumber}>{stats.totalCost?.toFixed(2) || '0.00'} ₽</p>
                    </div>
                    <div className={styles.statCard}>
                        <h3>Средний заказ</h3>
                        <p className={styles.statNumber}>{stats.avgOrderValue?.toFixed(2) || '0.00'} ₽</p>
                    </div>
                </div>
            )}

            <div className={styles.tableContainer}>
                <table className={styles.ordersTable}>
                    <thead>
                    <tr>
                        <th>Номер заказа</th>
                        <th>Поставщик</th>
                        <th>Кол-во товаров</th>
                        <th>Общая сумма</th>
                        <th>Статус</th>
                        <th>Дата создания</th>
                        <th>Действия</th>
                    </tr>
                    </thead>
                    <tbody>
                    {orders.map(order => (
                        <tr key={order._id}>
                            <td>
                                <strong>{order.orderNumber}</strong>
                            </td>
                            <td>{order.supplier?.name || 'Неизвестно'}</td>
                            <td>{order.totalQuantity}</td>
                            <td>{order.totalCost.toFixed(2)} ₽</td>
                            <td>
                                    <span
                                        className={styles.statusBadge}
                                        style={{
                                            backgroundColor: getStatusColor(order.status),
                                            color: '#fff'
                                        }}
                                    >
                                        {getStatusText(order.status)}
                                    </span>
                            </td>
                            <td>{new Date(order.createdAt).toLocaleDateString('ru-RU')}</td>
                            <td>
                                <button
                                    onClick={async () => {
                                        try {
                                            const response = await fetch(`http://localhost:5000/api/orders/${order._id}/status`, {
                                                method: 'PATCH',
                                                headers: {
                                                    'Content-Type': 'application/json',
                                                    'Authorization': `Bearer ${token}`
                                                },
                                                body: JSON.stringify({ status: 'delivered' })
                                            });
                                            const data = await response.json();
                                            if (data.success) {
                                                fetchOrders();
                                                fetchStats();
                                            }
                                        } catch (error) {
                                            console.error('Ошибка обновления:', error);
                                        }
                                    }}
                                    disabled={order.status === 'delivered' || order.status === 'cancelled'}
                                    className={styles.actionBtn}
                                >
                                    Доставлен
                                </button>
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>

            <div className={styles.inventorySection}>
                <h3>Управление заказами (классовый компонент)</h3>
                <InventoryManager
                    token={token}
                    showNotification={showNotification}
                />
            </div>
        </div>
    );
}

// Вспомогательные функции
const getStatusColor = (status) => {
    const colors = {
        'created': '#ffb74d',
        'confirmed': '#4fc3f7',
        'processing': '#9575cd',
        'shipped': '#64b5f6',
        'delivered': '#81c784',
        'cancelled': '#e57373'
    };
    return colors[status] || '#757575';
};

const getStatusText = (status) => {
    const texts = {
        'created': 'Создан',
        'confirmed': 'Подтвержден',
        'processing': 'В обработке',
        'shipped': 'Отправлен',
        'delivered': 'Доставлен',
        'cancelled': 'Отменен'
    };
    return texts[status] || status;
};

export default PurchaseHistory;
